import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"其他模式","description":"","frontmatter":{},"headers":[],"relativePath":"other/overview.md","filePath":"other/overview.md","lastUpdated":1791561689000}`),a={name:`other/overview.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="其他模式" tabindex="-1">其他模式 <a class="header-anchor" href="#其他模式" aria-label="Permalink to “其他模式”">​</a></h1><p>还有一些常见，但不好分类的模式</p><p>这些模式广泛应用于分层架构、数据访问和状态管理等场景，虽然不太好归入经典三类，但在工程实践中同样重要。</p><h3 id="本目录包含的模式" tabindex="-1">本目录包含的模式 <a class="header-anchor" href="#本目录包含的模式" aria-label="Permalink to “本目录包含的模式”">​</a></h3><ul><li><a href="/hello-design-patterns/other/mvc">MVC 模式</a>：把应用程序拆分为模型、视图、控制器，实现关注点分离。</li><li><a href="/hello-design-patterns/other/mvvm">MVVM 模式</a>：在 MVC 基础上引入 ViewModel，通过数据绑定分离视图与业务逻辑。</li><li><a href="/hello-design-patterns/other/orm">对象-关系映射（ORM）模式</a>：把数据库表映射为对象，用面向对象方式操作数据库。</li><li><a href="/hello-design-patterns/other/event-sourcing">事件溯源模式</a>：记录状态变化事件而非最终状态，以此重建状态并支持审计回溯。</li><li><a href="/hello-design-patterns/other/transaction-script">事务脚本模式</a>：把一个业务操作写成线性处理函数，规则跟流程走，与<a href="/hello-design-patterns/anti-patterns/anemic-domain-model">贫血模型</a>互为对照。</li><li><a href="/hello-design-patterns/other/repository">仓储与单元工作</a>：领域层拿聚合根的集合式接口，实现落基础设施层；单元工作把一次事务的整批改动包成一个数据库事务。</li></ul>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};